import itertools

def is_no_brbr_cyclic(c):
    n = len(c)
    for indices in itertools.combinations(range(n), 4):
        colors = tuple(c[i] for i in indices)
        if colors == ('B', 'R', 'B', 'R') or colors == ('R', 'B', 'R', 'B'):
            return False
    return True

def get_strategy(c):
    n = len(c)
    if all(x == c[0] for x in c):
        if c[0] == 'B':
            return (0,), ('B',)
        else:
            return (0, 1), ('R', 'R') # Using 2 points for all-R

    s = []
    for i in range(n):
        if c[i] != c[i-1]:
            s.append(i)
    return tuple(s), tuple(c[i] for i in s)

def check_strategy_general(n):
    colorings = [c for c in itertools.product('RB', repeat=n) if is_no_brbr_cyclic(c)]
    results = [get_strategy(c) for c in colorings]

    # results is a list of ((s_indices), (s_colors))
    for i in range(len(results)):
        s1, col1 = results[i]
        for j in range(len(results)):
            s2, col2 = results[j]
            k1, k2 = len(s1), len(s2)
            if k1 != k2: continue
            if k1 == 0: continue

            # Check all rotations r
            for r in range(n):
                rotated_s1 = sorted([(x + r) % n for x in s1])
                if tuple(rotated_s1) == s2:
                    # Mapping from s1 to s2
                    mapping = []
                    for val in s2:
                        for idx in range(k1):
                            if (s1[idx] + r) % n == val:
                                mapping.append(col1[idx])
                                break
                    if tuple(mapping) != col2:
                        return False, (i, j, r)
    return True, None

for n in range(3, 9):
    res, info = check_strategy_general(n)
    print(f"n={n}, success={res}")

