def check_strategy_with_f(f, n):
    colorings = [c for c in itertools.product('RB', repeat=n) if is_no_brbr_cyclic(c)]
    results = [f(c) for c in colorings]

    for i in range(len(results)):
        s1, col1 = results[i]
        for j in range(len(results)):
            s2, col2 = results[j]
            k1, k2 = len(s1), len(s2)
            if k1 != k2: continue
            if k1 == 0: continue

            for r in range(n):
                rotated_s1 = sorted([(x + r) % n for x in s1])
                if tuple(rotated_s1) == s2:
                    mapping = []
                    for val in s2:
                        for idx in range(k1):
                            if (s1[idx] + r) % n == val:
                                mapping.append(col1[idx])
                                break
                    if tuple(mapping) != col2:
                        return False
    return True

def strategy_boundary(c):
    n = len(c)
    # If all same, pick one point
    if all(x == c[0] for x in c):
        return (0,), (c[0],)
    # If not all same, pick the two boundary points
    s = []
    for i in range(n):
        if c[i] != c[i-1]:
            s.append(i)
    return tuple(s), tuple(c[i] for i in s)

